func TestOutputSearchResultsAgentKeepsSingleLiveEnvelope(t *testing.T) {
	t.Parallel()

	cmd := &cobra.Command{}
	var out bytes.Buffer
	cmd.SetOut(&out)

	flags := &rootFlags{asJSON: true, agent: true, compact: true}
	results := []json.RawMessage{json.RawMessage(`{"item":{"id":"168983602","title":"Wohnung"}}`)}
	if err := outputSearchResults(cmd, flags, results, 10, DataProvenance{Source: "live"}); err != nil {
		t.Fatalf("outputSearchResults returned error: %v", err)
	}

	var got map[string]any
	if err := json.Unmarshal(out.Bytes(), &got); err != nil {
		t.Fatalf("output is not JSON: %v\n%s", err, out.String())
	}
	meta, ok := got["meta"].(map[string]any)
	if !ok {
		t.Fatalf("top-level meta missing: %#v", got)
	}
	if source := meta["source"]; source != "live" {
		t.Fatalf("top-level meta.source = %v, want live; full output: %s", source, out.String())
	}
	resultsBytes, err := json.Marshal(got["results"])
	if err != nil {
		t.Fatalf("marshal nested results: %v", err)
	}
	if strings.Contains(string(resultsBytes), `"meta"`) {
		t.Fatalf("search --agent output is double-wrapped: %s", out.String())
	}
}

func TestShouldFallbackLiveSearchErrorOnlyForNetworkErrors(t *testing.T) {
	t.Parallel()

	networkErr := &url.Error{
		Op:  "Post",
		URL: "https://api.mobile.immobilienscout24.de/search/list",
		Err: &net.DNSError{Err: "no such host", Name: "api.mobile.immobilienscout24.de"},
	}
	if !shouldFallbackLiveSearchError(networkErr) {
		t.Fatalf("network errors should allow local fallback")
	}

	apiValidationErr := errors.New("POST /search/list returned HTTP 412: invalid realestatetype")
	if shouldFallbackLiveSearchError(apiValidationErr) {
		t.Fatalf("HTTP validation errors must not fall back to local results")
	}
}
